{
  "title": "The Gilded Cage",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Crumbling stone gates flanked by faded royal banners, with twisted iron portcullis half-raised. Dust and debris litter the ground.",
      "characters": ["Elena", "Garrick", "Lira"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings.",
      "visual_description": "Huddled figures in rags, peering from shattered windows and doorways. A child points toward a distant tower.",
      "characters": ["Elena", "Garrick", "Lira", "Townsfolk"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols block the main avenue.",
      "visual_description": "A squad of rusted but functional armor suits moves in formation, halberds glinting, their visors empty and dark.",
      "characters": ["Elena", "Garrick", "Lira", "Patrol Guard 1", "Patrol Guard 2", "Patrol Guard 3", "Patrol Guard 4"]
    },
    {
      "scene_number": 4,
      "caption": "They sneak through a collapsed market district.",
      "visual_description": "Overturned carts, faded awnings, and broken pottery. A large, tattered royal banner hangs from a half-fallen archway.",
      "characters": ["Elena", "Garrick", "Lira"]
    },
    {
      "scene_number": 5,
      "caption": "A magic door shimmers in a side alley.",
      "visual_description": "A stone doorframe carved with runes, the air within rippling like water. Faint whispers emanate from it.",
      "characters": ["Elena", "Garrick", "Lira"]
    },
    {
      "scene_number": 6,
      "caption": "Lira touches the door and is pulled inside.",
      "visual_description": "Lira’s hand passes through the shimmer, and vines erupt from the ground, dragging her into the portal. Elena and Garrick lunge too late.",
      "characters": ["Elena", "Garrick", "Lira"]
    },
    {
      "scene_number": 7,
      "caption": "The cursed tower looms ahead.",
      "visual_description": "A twisting spire of black stone, its top wreathed in unnatural green smoke. A single lit window pulses at the peak.",
      "characters": ["Elena", "Garrick"]
    },
    {
      "scene_number": 8,
      "caption": "Inside the tower, illusions of treasure fill the hall.",
      "visual_description": "Piles of gold coins, jeweled goblets, and silken tapestries line the walls. Shadows move at the edges of vision.",
      "characters": ["Elena", "Garrick"]
    },
    {
      "scene_number": 9,
      "caption": "Garrick resists a chest that speaks in his father's voice.",
      "visual_description": "A golden chest opens, and a holographic figure of an old man appears. Garrick hesitates, hand on his sword.",
      "characters": ["Elena", "Garrick"]
    },
    {
      "scene_number": 10,
      "caption": "They find Lira in a crystalline cage.",
      "visual_description": "A cage of translucent blue crystal hangs from chains. Lira is inside, unconscious, with runes glowing on the bars.",
      "characters": ["Elena", "Garrick", "Lira"]
    },
    {
      "scene_number": 11,
      "caption": "A spectral guardian appears to test them.",
      "visual_description": "A tall, armored figure made of pale blue light, wielding a massive ethereal sword. Its eyes are empty sockets.",
      "characters": ["Elena", "Garrick", "Spectral Guardian"]
    },
    {
      "scene_number": 12,
      "caption": "Elena breaks the cage with a shattering spell.",
      "visual_description": "Elena channels bright energy into the runes; cracks spider across the crystal. Lira stirs as the cage explodes into shards.",
      "characters": ["Elena", "Garrick", "Lira"]
    },
    {
      "scene_number": 13,
      "caption": "The tower begins to collapse as they flee downward.",
      "visual_description": "Stairs crumble, stones fall from above, and green fire licks the walls. The party stumbles through debris.",
      "characters": ["Elena", "Garrick", "Lira"]
    },
    {
      "scene_number": 14,
      "caption": "They emerge into a courtyard filled with more patrols.",
      "visual_description": "A wide courtyard with a central fountain overgrown with thorns. A dozen armored guards turn to face them.",
      "characters": ["Elena", "Garrick", "Lira", "Patrol Guard 1", "Patrol Guard 2", "Patrol Guard 3", "Patrol Guard 4", "Patrol Guard 5", "Patrol Guard 6"]
    },
    {
      "scene_number": 15,
      "caption": "A rumored dragon swoops overhead, scattering the guards.",
      "visual_description": "A massive red dragon with tattered wings glides low, breathing a line of fire that breaks the patrol formation.",
      "characters": ["Elena", "Garrick", "Lira", "Patrol Guard 1", "Patrol Guard 2", "Patrol Guard 3", "Patrol Guard 4", "Patrol Guard 5", "Patrol Guard 6", "Dragon"]
    },
    {
      "scene_number": 16,
      "caption": "They race toward the bridge, pursued by surviving guards.",
      "visual_description": "A narrow bridge of stone arches over a chasm. Behind them, guards regroup and give chase. The dragon circles higher.",
      "characters": ["Elena", "Garrick", "Lira"]
    },
    {
      "scene_number": 17,
      "caption": "On the bridge, a magical barrier seals the exit.",
      "visual_description": "A wall of pale blue energy crackles across the far end of the bridge. Beyond it, the countryside is visible.",
      "characters": ["Elena", "Garrick", "Lira"]
    },
    {
      "scene_number": 18,
      "caption": "Together they break the barrier and escape.",
      "visual_description": "Elena, Garrick, and Lira combine their strength—magic, steel, and will—to shatter the barrier. They cross the bridge as it collapses behind them.",
      "characters": ["Elena", "Garrick", "Lira"]
    }
  ]
}

